INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('54fad952-edbe-40e6-b0ee-e5f32e46caac', '21feff02-016d-46e2-bb9d-c27495133b1b', '82. óra: A százalékszámítás gyakorlása', 'Százalékérték kiszámítása következtetéssel (1% kiszámítása) vagy törtrésszel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "4f527cc2-8bbd-4f8e-a97a-051e80a552cc", "text": "Mennyi 500 Ft-nak a 10%-a? (500 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "f0382bab-a728-4126-8448-4f3c7d91e20c", "text": "Mennyi 500 Ft-nak az 1%-a? (500 / 100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "ef666a51-69bc-4172-bc94-08e535f2cc8c", "text": "Mennyi 500 Ft-nak a 20%-a? (500 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "4cfa65d7-424f-43a5-91f1-cb2a999f6808", "text": "Mennyi 800 kg-nak az 50%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "da254b9d-8416-4f8b-9b0e-b2a39d29baa0", "text": "A százalékérték kiszámításához az alapmennyiséget megszorozzuk a százaléklábbal és elosztjuk 100-zal.", "type": "true-false", "options": [{"id": "5b879ae5-4e63-4c07-a7cf-8ab4bb04e09c", "text": "Igaz", "isCorrect": true}, {"id": "156aaf34-6005-4bd2-a6f4-a18298e871a0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cc713d3f-f465-4f61-8385-8da1455d98e9", "text": "Mennyi 200 Ft-nak a 25%-a? (200 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "cbe0a264-881e-45d3-a0a9-ce3e25983533", "text": "Mennyi 1000 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}]'::jsonb, true, NOW()),
('4ae20ca7-2474-4e25-a88d-b79aec89332f', '21feff02-016d-46e2-bb9d-c27495133b1b', '83. óra: Feladatmegoldás', 'Százalékszámítással kapcsolatos hétköznapi szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "557dd6a3-93cb-45fe-ae96-e0bc425e8979", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezmény összege? (10000 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "c36d2b59-22c4-40f4-b694-0d732774ce26", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezményes ár? (10000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8000"}, {"id": "af0300bd-7c8b-4950-b22b-49e9c658376b", "text": "Egy iskolában 400 tanuló van. 55%-uk lány. Hány lány jár az iskolába? (400 * 0,55)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "220"}, {"id": "0469aa62-a6a8-41cb-a443-e0be5c9dd479", "text": "Hány fiú jár az iskolába? (400 - 220)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "31d9c227-43cc-4154-bef6-180d2153ca0f", "text": "A kedvezményes ár kiszámításához az eredeti árból kivonjuk a kedvezmény értékét.", "type": "true-false", "options": [{"id": "f7775b8e-d2bf-4eb8-a6bc-293d0b9c3497", "text": "Igaz", "isCorrect": true}, {"id": "cb23496d-b70a-4566-b51f-328a6dad2977", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c2e9b450-8313-40b2-bee6-3659fdaba487", "text": "Ha egy ár 10%-kal nő, az új ár az eredeti ár 110%-a lesz.", "type": "true-false", "options": [{"id": "56647c2d-ae87-455e-8e47-c95a1606dbcf", "text": "Igaz", "isCorrect": true}, {"id": "1b146ba7-35a7-4f7e-bb51-9514c3ce90c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a4256f14-5f77-4793-ac50-d4022940167a", "text": "Mennyi 50 000 Ft 5%-os kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}]'::jsonb, true, NOW()),
('87d35620-7b7c-426d-93a2-a733deff0c12', '21feff02-016d-46e2-bb9d-c27495133b1b', '84. óra: Feladatmegoldás II.', 'Összetettebb százalékszámítási feladatok, árleértékelések, drágulások.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "b0981598-12d5-495e-95ef-f2d9d193fcd6", "text": "Egy 20 000 Ft-os kabát árát 15%-kal felemelték. Hány Ft a drágulás értéke? (20000 * 0,15)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "6aeaf590-758b-46bf-9e7e-1f1dcebb5a8f", "text": "Mennyi a kabát új ára a 15%-os drágulás után? (20000 + 3000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "23000"}, {"id": "c7f92079-2d34-4d3e-8e87-c2b114d352a4", "text": "A 30-as létszámú osztályban a tanulók 10%-a hiányzott. Hány tanuló hiányzott?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "809f260a-a5ca-4fc5-aa3c-f88826f19e93", "text": "Hány tanuló volt jelen az osztályban? (30 - 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "8d6a3201-372b-45fe-a3b9-22338b835ea1", "text": "Ha a 100 Ft-os termék ára 50%-kal csökken, majd a kedvezményes ár 50%-kal nő, az ár visszatér 100 Ft-ra.", "type": "true-false", "options": [{"id": "a1e8b729-4fd7-41ce-b7fc-d02be26bb9b7", "text": "Igaz", "isCorrect": false}, {"id": "382375e9-3975-4359-846d-30e97d0990a2", "text": "Hamis (50 Ft 50%-os növekedése 75 Ft lesz!)", "isCorrect": true}], "timeLimit": 15}, {"id": "80f61e73-ddb1-4606-9a52-56f3e50a4be1", "text": "Mennyi 400 liter 75%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "57e19ac0-ce95-4fe9-925d-4c603a4ebdbb", "text": "A százalékszámítás alapvető ismeret a mindennapi pénzügyi tájékozódáshoz.", "type": "true-false", "options": [{"id": "17bc9df3-1fb7-42c2-845a-13d3c11be229", "text": "Igaz", "isCorrect": true}, {"id": "27a3d1e5-31a2-4919-ae15-976ee8884132", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());